  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2017, 2019],
      "pattern": "shock",
      "direction": "decrease",
      "magnitude": "A/E dropped to ~0.74-0.77 (~0.30 below baseline), then reverted to ~1.08 in 2020-2024",
      "confidence": 0.9,
      "evidence": [
        "ae_ip_by_year.csv: abrupt drop from 1.156 (2016) to 0.769 (2017), flat through 2018-2019, then sharp recovery to 1.074+ in 2020"
      ],
      "recommended_action": "Investigate 2017 IP claims incidence and underwriting guidelines for changes; assess macroeconomic or claims-handling impacts; termination rates by diagnosis are clean, suggesting incidence or overall duration drivers."
    },
    {
      "benefit": "Death",
      "years": [2017, 2019],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "A/E elevated to ~1.15-1.22 (+0.20), reverting to ~0.94 in 2020",
      "confidence": 0.4,
      "evidence": [
        "ae_death_by_year.csv: 3-year elevation, but empirical SD (0.165) is 3.5x Poisson, limiting statistical significance (~1.3x empirical SD)"
      ],
      "recommended_action": "Monitor for persistence; review cause-of-mortality and large claims in 2017-2019; likely within expected overdispersion rather than a structural shift."
    }
  ]
}

